/**
 * The sign-on artwork: the wordmark for the dialog's head, and the three figures below it,
 * one per step.
 *
 * All four are transparent cutouts rather than finished panels. The earlier crops carried
 * their own background, which never quite matched the lavender behind them and showed as a
 * lighter rectangle where the image began — a cutout composites onto whatever colour the
 * dialog happens to use and cannot have a seam at all. The wordmark arrived on a flat cream
 * card, so that card is keyed out here for the same reason.
 *
 * Base64 for the same reason as the sounds: neither svelte-package nor the CLI's bun build
 * is guaranteed to carry a binary asset through to dist.
 */

/** PNG bytes by name, base64. Served at `/__postboi/api/art/:name`. */
export const ART: Record<string, string> = {
	logo: "",
	locating:
		"",
	connecting:
		"",
	intercepting:
		"",
}
